  };

  const computePath = (input: string, format: Format) => {
    const [cwd, stem] = dirAndStem(input);
    const mkOutputdir = format.render[kLatexOutputDir];
    return mkOutputdir
      ? join(mkOutputdir, stem + ".pdf")
      : join(cwd, stem + ".pdf");
  };

  return texToPdfOutputRecipe(
    input,
    finalOutput,
    options,
    format,
    "latex",
    {
      generate,
      computePath,
    },
    outputDir,
  );
}

